import re, sys
from bs4 import BeautifulSoup
EVENT_RE = re.compile(r'^on', re.I)
BAD_SCHEME_RE = re.compile(r'^[\s\x00-\x1f]*(javascript|vbscript)\s*:', re.I)
FRAME_TAGS = ('iframe', 'frame', 'object', 'embed')

def clean(tag):
    if tag.name in ('script', 'noscript'):
        tag.decompose()
        return
    for name in list(tag.attrs):
        value = tag.attrs[name]
        if isinstance(value, list):
            value = ' '.join(value)
        if EVENT_RE.match(name):
            del tag[name]
        elif name in ('href', 'src', 'action') and BAD_SCHEME_RE.match(value):
            del tag[name]
        elif tag.name in FRAME_TAGS and name in ('data', 'src', 'href') and re.match(r'^[\s\x00-\x1f]*data:', value, re.I):
            del tag[name]

if len(sys.argv) < 2:
    sys.exit(1)
path = sys.argv[1]
with open(path, 'r', encoding='utf-8') as f:
    soup = BeautifulSoup(f.read(), 'html.parser')
for tag in list(soup.find_all(True)):
    clean(tag)
with open(path, 'w', encoding='utf-8') as f:
    f.write(str(soup))
PYEOF
